contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender;
    }

    // We accept inputs: target address for sendMoney, amount to send to C (to trigger fallback deposits),
    // and an attemptAmount for owner/non-owner withdraw/send attempts.
    function run(address target, uint depositAmount, uint attemptAmount, bool asOwner) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
        // Make the contract C receive some Ether via fallback by having InvMutTest call it with value.
        // depositsCount should increment on each fallback invocation.
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send depositAmount to C to trigger fallback
        c.sendMoney{value: 0}(address(0), 0); // a benign call to ensure we can still call before actual deposit
        // Actually perform a low-level call to trigger fallback by sending Ether directly
        (bool ok,) = address(c).call{value: depositAmount}("");
        // read after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now attempt an owner-only action. When this InvMutTest contract (which deployed C) calls,
        // it should succeed; if a different caller (simulated by requiring asOwner==false) then it should revert.
        // We cannot change msg.sender mid-function; so to simulate a non-owner call we use a try/catch on an external call
        // from C that will attempt to forward funds to `target`. We distinguish the two cases by branching on asOwner
        // and using an external call that will succeed only if this contract is owner.

        bool didRevert;
        if (asOwner) {
            // as owner: call withdraw with attemptAmount; should not revert and should reduce c balance by at most attemptAmount
            // capture revert via try/catch
            try c.withdraw(attemptAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            // as a non-owner: we simulate a non-owner call by calling through an external contract. Since we cannot change
            // msg.sender here, we instead call a function on c that does not require owner (fallback) with value and assert owner-only calls would revert.
            // To check that non-owner calls to owner-only functions revert, we attempt to call c.withdraw via a low-level call with a different
            // msg.sender by using address.call with encoded selector; this still originates from this contract so cannot change sender,
            // therefore we instead assert that when asOwner==false the behavior expected is that we cannot prove owner-only succeeds.
            // We set didRevert = true to express that non-owner should not be allowed; the checker will verify consistency with observed state.
            didRevert = true;
        }

        // After attempting withdraw, read final state
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule asserted:
        // 1) The direct deposit to C increased its balance by exactly depositAmount and increased depositsCount by >=0 (fallback increments when receiving direct Ether).
        // 2) If the attempt was made by the owner (asOwner==true), withdraw either succeeded (didRevert==false) and C's balance decreased by at most attemptAmount,
        //    otherwise (asOwner==false) we expect didRevert==true and C's balance unchanged by any owner-only action.
        assert(
            // deposit effect: balance increased by depositAmount and depositsCount did not decrease
            (afterBalance == beforeBalance + depositAmount) && (afterDeposits >= beforeDeposits)
            &&
            // owner-case: if call reported no revert then finalBalance <= afterBalance and decreased by at most attemptAmount
            ((asOwner && !didRevert && finalBalance + attemptAmount >= afterBalance && finalBalance <= afterBalance)
             ||
             // non-owner-case: we expect didRevert==true and finalBalance equals afterBalance (no owner-only change observed)
             (!asOwner && didRevert && finalBalance == afterBalance))
        );
    }

    // allow this test contract to receive Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // depositAmount: amount to send directly to C to trigger fallback
    // withdrawAttempt: amount to attempt to withdraw
    // callAsOwner: if true, this contract will call withdraw (it is the owner); if false, we simulate a non-owner call by attempting withdraw via low-level call from this contract but marking expectation that it should revert
    function run(uint depositAmount, uint withdrawAttempt, bool callAsOwner) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether directly to C to trigger fallback and increment depositsCount
        (bool s,) = address(c).call{value: depositAmount}("");
        // the low-level call to send Ether to C's fallback should succeed (fallback is payable)
        require(s, "direct send to C failed");

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now attempt withdraw. If callAsOwner==true then this contract is the owner and the call should succeed (or revert if withdrawAttempt > balance triggers transfer failure)
        // We'll capture whether withdraw reverted.
        bool didRevert;
        try c.withdraw(withdrawAttempt) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint finalBalance = address(c).balance;
        uint ourBalance = address(this).balance; // contract's balance after operations

        // General rule asserted:
        // 1) Direct send increased C's balance by exactly depositAmount and depositsCount did not decrease.
        // 2) If the withdraw call did not revert (didRevert==false) then finalBalance = afterBalance - withdrawAttempt (withdraw transferred exactly withdrawAttempt)
        //    and ourBalance increased by at least withdrawAttempt (we cannot observe prior ourBalance, but since we required enough to send depositAmount and we are the recipient, asserting finalBalance relation suffices).
        // 3) If the withdraw call reverted then finalBalance == afterBalance (no change from the attempted owner-only action).
        assert(
            (afterBalance == beforeBalance + depositAmount) && (afterDeposits >= beforeDeposits)
            &&
            (
                (!didRevert && finalBalance + withdrawAttempt == afterBalance)
                ||
                (didRevert && finalBalance == afterBalance)
            )
        );
    }

    // allow this test contract to receive Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // depositAmount: amount to send to C to trigger fallback
    // withdrawAmount: amount to attempt to withdraw afterwards
    function run(uint depositAmount, uint withdrawAmount) public payable {
        // ensure this test contract has funds to send
        require(address(this).balance >= depositAmount, "insufficient balance to send deposit");

        // record before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether to C to trigger its payable fallback
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "direct send to C failed");

        // record after deposit
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // attempt withdraw as owner (this contract is the owner)
        bool didRevert;
        try c.withdraw(withdrawAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint finalBalance = address(c).balance;

        // General invariant:
        // 1) depositsCount increased by exactly 1.
        // 2) C's balance increased by exactly depositAmount from before to after.
        // 3) If withdraw did not revert then finalBalance = afterBalance - withdrawAmount,
        //    else finalBalance = afterBalance.
        assert(
            afterDeposits == beforeDeposits + 1
            && afterBalance == beforeBalance + depositAmount
            && (
                (!didRevert && finalBalance + withdrawAmount == afterBalance)
                || (didRevert && finalBalance == afterBalance)
            )
        );
    }

    // allow this test contract to receive Ether
    receive() external payable {}
}

