contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters to drive calls and Ether
    function run(address payable possibleOwner, uint sendAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for sendAmount");
        // record observable state before any actions
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // 1) Try calling fallback by sending Ether to c (this will increment depositsCount)
        // Use a top-level state-changing call
        c.sendMoney(address(c), sendAmount);

        // read after values
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // For withdraw and withdrawAll and sendMoney, they are protected by onlyOwner.
        // Our test contract is NOT the original owner (C's owner is the deployer of C),
        // so calls that require onlyOwner must revert when invoked by this contract.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(possibleOwner, withdrawAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Assert a single general rule:
        // - The fallback/increment via sending to contract happened exactly once (depositsCount increased by 1)
        // - And none of the owner-only actions succeeded when called by this contract (they must revert)
        assert(midDeposits == beforeDeposits + 1 && midBalance == beforeBalance && withdrewReverted && withdrawAllReverted && sendMoneyReverted);
    }

    // receive to accept Ether if needed
    receive() external payable {}
}

