contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try calling withdraw, withdrawAll, sendMoney as non-owner
    // provide a value to send with sendMoney; ensure this contract has that Ether
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt withdrawAll (should revert because this contract is not owner)
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Attempt withdraw with some amount
        bool revertedWithdraw;
        try c.withdraw(amount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Attempt sendMoney forwarding `amount` wei to c itself
        bool revertedSend;
        // ensure we have balance to forward
        if (amount > 0) {
            // top-level state-changing call with value
            try c.sendMoney{value: amount}(address(c), amount) {
                revertedSend = false;
            } catch {
                revertedSend = true;
            }
        } else {
            // when amount==0, still call without value
            try c.sendMoney(address(c), amount) {
                revertedSend = false;
            } catch {
                revertedSend = true;
            }
        }

        // observe after state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: since InvMutTest is not the owner, all three calls must revert,
        // and none of them may change the contract balance or depositsCount.
        assert(revertedWithdrawAll && revertedWithdraw && revertedSend && afterDeposits == beforeDeposits && afterBalance == beforeBalance);
    }

    // allow receiving Ether into this test contract
    receive() external payable {}
}

