contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint amount) public payable {
        // ensure this test contract has enough balance to forward `amount` if we need to send value via low-level: we'll use sendMoney by letting c call target, so ensure balance for sending to c
        require(address(this).balance >= amount);

        // observe before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt withdrawAll (should revert because this contract is not owner)
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Attempt withdraw with some amount
        bool revertedWithdraw;
        try c.withdraw(amount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Attempt sendMoney: we must call it as a state-changing call at top-level.
        // To forward Ether to c via sendMoney, we call sendMoney and provide value from this contract to c by sending value in the external call to c.
        // Solidity disallows setting value on an arbitrary function type in try; instead, perform two branches: if amount>0, call using low-level via address(c).call{value: amount} with encoded selector for sendMoney.
        bool revertedSend;
        if (amount > 0) {
            // prepare calldata for sendMoney(address,uint)
            bytes memory data = abi.encodeWithSelector(c.sendMoney.selector, address(c), amount);
            (bool ok, ) = address(c).call{value: amount}(data);
            revertedSend = !ok;
        } else {
            try c.sendMoney(address(c), amount) {
                revertedSend = false;
            } catch {
                revertedSend = true;
            }
        }

        // observe after state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: since InvMutTest is not the owner, all three calls must revert,
        // and none of them may change the contract balance or depositsCount.
        assert(revertedWithdrawAll && revertedWithdraw && revertedSend && afterDeposits == beforeDeposits && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: callerIsOwner indicates whether this contract should act as owner (true)
    // or we will simulate a non-owner by having the contract call sendMoney first to transfer ownership-like funds
    // amount is the Ether to attempt to withdraw; must be <= address(c).balance for meaningful test when owner.
    function run(bool callerIsOwner, uint amount) public payable {
        require(true);

        // Observe initial public state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address owner = c.owner();

        // If callerIsOwner is false, we need to ensure this contract is not the owner.
        // The deployment semantics: owner was set to the original deployer of C, which is the test deployer of this framework,
        // not this InvMutTest contract. So in general this contract is not owner. We don't change owner here.

        // Try withdraw and catch whether it reverts
        bool reverted;
        try c.withdraw{value: 0}(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Also try withdrawAll and catch whether it reverts
        bool revertedAll;
        try c.withdrawAll{value: 0}() {
            revertedAll = false;
        } catch {
            revertedAll = true;
        }

        // Read post-state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // If this contract is not the owner, both withdraw and withdrawAll must revert, and the contract's balance and depositsCount remain unchanged.
        // If this contract is the owner, at least one of withdraw or withdrawAll may succeed; we only assert the non-owner invariant.
        if (address(this) != owner) {
            assert(reverted && revertedAll && afterBalance == beforeBalance && afterDeposits == beforeDeposits);
        }

        // If address(this) == owner, make a weaker assertion to ensure the test's single assert requirement is satisfied for all inputs:
        // When it is owner, withdrawing cannot increase the contract balance and depositsCount is only changed by fallback (not by withdraw),
        // so afterBalance <= beforeBalance and afterDeposits >= beforeDeposits.
        else {
            assert(afterBalance <= beforeBalance && afterDeposits >= beforeDeposits);
        }
    }

    receive() external payable {}
}

