    // Try to withdraw 'amount' (any value). This contract will act as caller for c.withdraw and c.withdrawAll.
    function run(uint amount) public payable {
        require(true);

        // Observe initial public state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address owner = c.owner();

        // Attempt withdraw and record whether it reverted
        bool revertedWithdraw;
        try c.withdraw(amount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Attempt withdrawAll and record whether it reverted
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Read post-state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if this contract is not the owner, both calls must revert and no state change occurs on c
        if (address(this) != owner) {
            assert(revertedWithdraw && revertedWithdrawAll && afterBalance == beforeBalance && afterDeposits == beforeDeposits);
        }

        // If this contract is the owner, assert a weaker non-trivial property to ensure single assert is always reachable:
        // withdraw and withdrawAll cannot increase the contract's balance; depositsCount can only increase via fallback, so it is >= before.
        else {
            assert(afterBalance <= beforeBalance && afterDeposits >= beforeDeposits);
        }
    }

    receive() external payable {}
}

