        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // If the call succeeded, depositsCount must increase by exactly 1 and balance increase by amount.
        // If the call reverted, neither depositsCount nor balance should have increased.
        assert( (ok && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
             || (!ok && afterCount == beforeCount && afterBal == beforeBal) );
    }

    receive() external payable {}
}

