        // - If we did not perform the call, nothing changes.
        // - If we performed the call and it reverted, counts and balances are unchanged.
        // - If we performed the call and it succeeded, then C.balance increased by exactly amount
        //   and depositsCount increased by exactly 1 (i.e., at most 1 and here exactly 1),
        //   and this contract's balance decreased by exactly amount.
        assert(
            (!doCall && afterCount == beforeCount && afterC == beforeC && afterThis == beforeThis)
            || (doCall && reverted && afterCount == beforeCount && afterC == beforeC && afterThis == beforeThis)
            || (doCall && !reverted && afterC == beforeC + amount && afterCount == beforeCount + 1 && afterThis + amount == beforeThis)
        );
    }

    // Accept Ether when C forwards to us (if that ever happens in other tests).
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We implement a single public payable function that attempts to invoke C's fallback
    // by making a low-level call to the contract address with a given value and calldata.
    // It records c.depositsCount() and address(c).balance before and after, and records
    // whether the low-level call reverted. The assert states the general relation between
    // depositsCount, balances, and revert behavior for all inputs.
    function run(address targetCalldata, uint value, bytes calldata extra) public payable {
        // require we have enough Ether to forward 'value'
        require(address(this).balance >= value);

        // read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // perform a low-level call to trigger fallback; use provided calldata to allow empty or non-empty
        bool success;
        bytes memory ret;
        (success, ret) = address(c).call{value: value}(abi.encodePacked(targetCalldata, extra));

        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // If the call succeeded then C's balance must have increased by exactly 'value'
        // and depositsCount must have increased by exactly 1 (fallback increments by 1 per call).
        // If the call reverted then neither balance nor depositsCount changed.
        assert(
            (success && afterBal == beforeBal + value && afterCount == beforeCount + 1)
            || (!success && afterBal == beforeBal && afterCount == beforeCount)
        );
    }

    // Allow this test contract to receive refunds from C.withdraw or send operations.
    receive() external payable {}
}

contract InvMutTest {
