        // or the call reverted and neither balance nor depositsCount changed.
        assert(
            (success && afterBal == beforeBal + value && afterCount == beforeCount + 1)
            || (!success && afterBal == beforeBal && afterCount == beforeCount)
        );
    }

    // allow receiving Ether from C.withdraw/send
