    // run is payable to allow sending Ether when calling c, but for this property we test non-owner calls.
    function run(address target, uint value) public payable {
        require(true);

        // record before state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // ensure this contract has enough balance to attempt sending value to c if we choose to
        // (we won't send Ether to c in the call itself because sendMoney is non-payable from caller side)
        // Attempt call as a non-owner: since msg.sender for calls to c will be this contract,
        // and c.owner was set to the deployer of c (not this contract), this contract is non-owner.
        bool reverted;
        try c.sendMoney(target, value) {
