        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: when invoked by non-owner, c's balance and depositsCount cannot increase or decrease;
        // i.e., they must remain equal to their before values (call either reverts or is a no-op on state)
        assert(afterBalance == beforeBalance && afterDeposits == beforeDeposits);
    }

