        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Call withdrawAll as owner (this contract). Capture whether it reverted.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: If withdrawAll returns (does not revert), then C.balance becomes 0 (all funds withdrawn)
        // and depositsCount does not increase. If it reverts, no requirement is made.
        assert(reverted || (afterBalance == 0 && afterDeposits >= beforeDeposits));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We receive Ether when withdraw/send transfers to this contract.
    receive() external payable {}

    // params: amount to send from C to itself via sendMoney, and gasless dummy target flag
    function run(address target, uint value) public payable {
        require(true);

        // pre-read observable state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // We must be the owner of c because this contract deployed c in the harness
        // Call sendMoney on c, but choose target parameter provided by the caller.
        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if we invoked sendMoney with target == address(c), then either it reverted
        // and nothing changed, or it returned and depositsCount increased by exactly 1 (fallback executed)
        // and C.balance did not increase (it may stay same or decrease if funds forwarded internally).
        if (target == address(c)) {
            assert(
                (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                || (!reverted && afterDeposits == beforeDeposits + 1 && afterBalance <= beforeBalance)
            );
        } else {
            // If target != c, then we assert a weaker general invariant: either reverted with no changes,
            // or if returned then depositsCount did not decrease (fallback won't be triggered on C itself)
            assert(
                (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                || (!reverted && afterDeposits >= beforeDeposits)
            );
        }
    }
}

