    // ownerCallValue: amount that owner (this contract) will instruct C to send to this contract via sendMoney
    function run(uint ownerCallValue) public payable {
        // This test requires that this contract is the owner of c so sendMoney will be allowed.
        require(c.owner() == address(this));

        // record before state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // ensure we have enough balance to represent potential outgoing transfer from C later is not needed here
        // call sendMoney with target = address(this)
        bool reverted;
        try c.sendMoney(address(this), ownerCallValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // record after state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // If the call reverted then C's balance and depositsCount must be unchanged.
        // If the call returned then C.balance cannot have increased by more than ownerCallValue,
        // and depositsCount either increased by exactly 1 (if C received a plain transfer to its fallback) or stayed same.
        // We express "depositsCount increased by exactly 1 iff C received plain Ether" by allowing only +0 or +1.
        assert(
            (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
            || (!reverted && afterBalance <= beforeBalance + ownerCallValue && (afterDeposits == beforeDeposits || afterDeposits == beforeDeposits + 1))
        );
    }
