contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // receive to accept Ether if C calls back into this contract
    receive() external payable {}

    // single public test: ownerCallValue is the value passed to sendMoney
    function run(uint ownerCallValue, address target) public payable {
        // require this test contract to be the owner so sendMoney is allowed
        require(c.owner() == address(this));

        // record before state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // ensure this test contract has enough balance to fund any potential external behavior
        // (not strictly necessary for calling sendMoney since C pays out, but ensures safety if test forwards Ether)
        // We don't use msg.value; any Ether this contract needs would be pre-funded by the harness.

        bool reverted;
        try c.sendMoney(target, ownerCallValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule:
        // - depositsCount never decreases (fallback only increments it on plain transfers)
        // - if call returned then C's balance cannot have decreased by more than ownerCallValue
        //   i.e., beforeBalance - afterBalance <= ownerCallValue  (rewrite to avoid underflow using afterBalance >= beforeBalance - ownerCallValue is unsafe),
        //   so we assert afterBalance >= beforeBalance - ownerCallValue when ownerCallValue <= beforeBalance, otherwise allow any non-negative afterBalance.
        // To keep the assert purely over observable values and params and avoid underflow, we express:
        // if !reverted then afterBalance + ownerCallValue >= beforeBalance

        assert(
            // depositsCount never decreases
            afterDeposits >= beforeDeposits
            && (
                // if reverted, balances unchanged
                (reverted && afterBalance == beforeBalance)
                ||
                // if not reverted, C cannot lose more than ownerCallValue: afterBalance + ownerCallValue >= beforeBalance
                (!reverted && afterBalance + ownerCallValue >= beforeBalance)
            )
        );
    }
}

