contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Caller (this contract) is the owner of c because c was deployed by this test harness's deployer
    // We need a function that takes an arbitrary target and value and simulates a non-owner call.
    // To become a non-owner when calling c, we perform the call via an externalcall: we create
    // an internal helper contract NonOwnerCaller deployed from here, and it will call c.sendMoney.

    function run(address target, uint value) public payable {
        require(address(this).balance >= value);

        // record before state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Deploy a helper contract from this test that will call c.sendMoney; that helper's address
        // will be different from the original owner (the deployer of c), so it will be a non-owner.
        NonOwnerCaller helper = new NonOwnerCaller(c);

        bool reverted;
        // try calling sendMoney from non-owner helper
        try helper.callSendMoney{value: value}(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if the call was made by a non-owner, then either it reverted or it left C's
        // balance and depositsCount unchanged. Thus (reverted || (after == before)).
        assert(reverted || (afterBalance == beforeBalance && afterDeposits == beforeDeposits));
    }

    // helper contract that is NOT the original owner of c (since deployed by this test contract)
    // It will attempt to call c.sendMoney forwarding some Ether.
    receive() external payable {}
}

contract NonOwnerCaller {
    C c;
    constructor(C _c) payable { c = _c; }
    // payable so the InvMutTest can fund this contract before calling
    function callSendMoney(address target, uint value) public payable {
        // forward the provided value to c.sendMoney
        c.sendMoney{value: value}(target, value);
    }
}
